/// <summary>
/// NDX_MultipleSelect
/// </summary>
abstract class NDX_MultipleSelect
{
    Args                    args_SelectForm;
    FormRun                 selectForm;
    NDX_ItemValidity        oItemValidity;
    NDXItemValidityErrors   itemValidityErrors;

}

Method.Source:
public NDX_ItemValidity parmOItemValidity(NDX_ItemValidity _oItemValidity = oItemValidity)
{
    oItemValidity = _oItemValidity;
    return oItemValidity;
}

protected void new()
{
    args_SelectForm = new Args();
}

/// <summary>
/// Initalizes args object for form
/// </summary>
public void initArgsForSelectForm()
{
    ;
    args_SelectForm.parmObject(this);
}

/// <summary>
/// abstract close select Form
/// </summary>
abstract void closedSelectForm()
{
}

/// <summary>
/// opens selected form
/// </summary>
void openSelectForm()
{
    ;
    this.initArgsForSelectForm();

    selectForm = ClassFactory.formRunClass(args_SelectForm);
    selectForm.init();
    selectForm.run();
    selectForm.wait();

    this.closedSelectForm();
}
